const fastenalMetaContent = (html: string, name: string): string | null => {
  if (!/^[a-z_]+$/i.test(name)) return null;
  for (const match of html.matchAll(/<meta\b[^>]*>/gi)) {
    const tag = match[0];
    const tagName = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)')/i)?.slice(1).find(Boolean);
    if (tagName !== name) continue;
    return tag.match(/\bcontent\s*=\s*(?:"([^"]*)"|'([^']*)')/i)?.slice(1).find(Boolean)?.trim() ?? null;
  }
  return null;
};

const fastenalSessionCookie = (headers: Headers): string | null => {
  const values = (headers as Headers & { getSetCookie?: () => string[] }).getSetCookie?.()
    ?? [headers.get("set-cookie") ?? ""];
  const session = values.join(",").match(
    /(?:^|,\s*)JSESSIONID=(?:"([A-Za-z0-9._~:-]{8,256})"|([A-Za-z0-9._~:-]{8,256}))(?:;|,|$)/i,
  );
  const value = session?.[1] ?? session?.[2];
  return value ? `JSESSIONID=${session?.[1] ? `"${value}"` : value}` : null;
};

const fastenalDate = (value: string | null): string | null => {
  const match = value?.match(/^(\d{2})-(\d{2})-(\d{4})$/);
  if (!match) return null;
  const month = Number(match[1]);
  const day = Number(match[2]);
  const year = Number(match[3]);
  const parsed = new Date(Date.UTC(year, month - 1, day));
  return parsed.getUTCFullYear() === year && parsed.getUTCMonth() === month - 1 && parsed.getUTCDate() === day
    ? parsed.toISOString()
    : null;
};

const fastenalNamedDate = (value: string | null): string | null => {
  const match = value?.match(/^(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2}),\s*(\d{4})$/i);
  if (!match) return null;
  const month = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
  ].indexOf(match[1].toLocaleLowerCase());
  const day = Number(match[2]);
  const year = Number(match[3]);
  const parsed = new Date(Date.UTC(year, month, day));
  return month >= 0 && parsed.getUTCFullYear() === year && parsed.getUTCMonth() === month && parsed.getUTCDate() === day
    ? parsed.toISOString()
    : null;
};

const fastenalPublishedDate = (value: unknown): string | null => {
  if (typeof value !== "number" || !Number.isSafeInteger(value)) return null;
  const date = new Date(value);
  return Number.isNaN(date.valueOf()) || date.getUTCFullYear() < 2000 || date.getUTCFullYear() > 2100
    ? null
    : date.toISOString();
};

const fastenalSearchBody = (): URLSearchParams => new URLSearchParams({
  draw: "1",
  start: "0",
  length: "1000",
  query: "",
  sortColumn: "5",
  sortDir: "desc",
  type: "",
  countryLocalityId: FASTENAL_US_COUNTRY_LOCALITY_ID,
  stateLocalityId: "",
  stateAbbreviation: "",
  distanceInMiles: "",
  zip: "",
  departmentIdList: "",
  states: "",
});

const fastenalListingJob = (value: FastenalListingJob, source: CrawlSource): CrawledJob | null => {
  const externalId = typeof value.jobId === "number" && Number.isSafeInteger(value.jobId)
    ? String(value.jobId)
    : null;
  const title = asText(value.title);
  const city = asText(value.city);
  const state = asText(value.state);
  const department = asText(value.department);
  const listedType = asText(value.type);
  const sourcePostedText = fastenalPublishedDate(value.approvedDate);
  const endDateText = asText(value.endDate);
  const validThrough = fastenalDate(endDateText);
  const stateParts = state?.split(",").map((part) => part.trim()).filter(Boolean) ?? [];
  const states = stateParts.filter((part) => part !== "TBD");
  const locationCity = city?.replace(/,\s*TBD$/i, "").trim() ?? null;
  if (!externalId || !/^\d{3,12}$/.test(externalId) || !title || !city || !state
    || stateParts.length < 1 || stateParts.some((part) => part !== "TBD" && !/^[A-Z]{2}$/.test(part))
    || states.length < 1 || !locationCity
    || !department || !listedType || !sourcePostedText || !validThrough) return null;
  const location = [locationCity, ...states].join(", ");
  const programs = classifyJobPrograms(title).keys;
  return {
    externalId,
    requisitionId: externalId,
    title,
    company: source.company,
    location,
    locationCity,
    ...(states.length === 1 ? { locationState: states[0] } : {}),
    locationCountry: "United States",
    arrangement: /\bremote\b/i.test(`${title} ${city}`) ? "remote" : "unknown",
    employmentType: programs.includes("coop") ? "Co-op"
      : programs.includes("internship") ? "Internship"
        : normalizeEmploymentType(listedType) ?? listedType,
    department,
    summary: null,
    sourcePostedText: sourcePostedText.slice(0, 10),
    publishedAt: sourcePostedText,
    validThrough,
    officialUrl: `https://jobs.fastenal.com/details/${externalId}`,
  };
};

const fastenalDetailJob = async (
  job: CrawledJob,
  source: CrawlSource,
  fetcher: typeof fetch,
  cookie: string,
): Promise<CrawledJob | null> => {
  try {
    const response = await fetchWithTimeout(fetcher, job.officialUrl, {
      headers: { accept: "text/html,application/xhtml+xml", cookie, referer: FASTENAL_JOB_SEARCH_URL },
    }, true, { attempts: 1, timeoutMs: 6_000 });
    if (!response.ok) return null;
    const finalUrl = new URL(response.url || job.officialUrl);
    if (finalUrl.origin !== "https://jobs.fastenal.com" || finalUrl.pathname !== `/details/${job.externalId}`
      || finalUrl.search || finalUrl.hash || finalUrl.username || finalUrl.password || finalUrl.port) return null;
    const html = await response.text();
    const fields = new Map([...html.matchAll(/<tr\b[^>]*>\s*<td\b[^>]*>([\s\S]*?)<\/td>\s*<td\b[^>]*>([\s\S]*?)<\/td>\s*<\/tr>/gi)]
      .flatMap((match): Array<[string, string]> => {
        const key = icimsText(match[1]);
        const value = icimsText(match[2]);
        return key && value ? [[key, value]] : [];
      }));
    const title = fields.get("Title") ?? null;
    const externalId = fields.get("Job ID") ?? null;
    const listedType = fields.get("Type") ?? null;
    const location = fields.get("Location")?.replace(/\s+\d{5}(?:-\d{4})?$/, "") ?? null;
    const department = fields.get("Departments") ?? null;
    const sourcePostedText = fields.get("Date Published") ?? null;
    const endDateText = fields.get("End Date") ?? null;
    const publishedAt = fastenalNamedDate(sourcePostedText);
    const validThrough = fastenalDate(endDateText);
    const description = icimsText(html.match(
      /<div\b[^>]*class=["'][^"']*\bcms-job-description\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i,
    )?.[1]);
    const applyUrl = anchorsFromHtml(html).flatMap(({ href, text }) => {
      if (!/^apply now$/i.test(text)) return [];
      try {
        const url = new URL(href, job.officialUrl);
        return url.origin === "https://jobs.fastenal.com" && url.pathname === `/careers/application/${job.externalId}`
          && !url.search && !url.hash && !url.username && !url.password && !url.port ? [url.href] : [];
      } catch {
        return [];
      }
    }).at(0) ?? null;
    if (!externalId || externalId !== job.externalId || !title || jobIdentityText(title) !== jobIdentityText(job.title)
      || !listedType || !location || location !== job.location || !department || department !== job.department
      || !sourcePostedText || !publishedAt || publishedAt.slice(0, 10) !== job.publishedAt?.slice(0, 10)
      || !validThrough || validThrough !== job.validThrough || !description || description.length < 100 || !applyUrl) return null;
    const programs = classifyJobPrograms(`${title} ${description}`).keys;
    return {
      ...job,
      company: source.company,
      employmentType: programs.includes("coop") ? "Co-op"
        : programs.includes("internship") ? "Internship"
          : normalizeEmploymentType(listedType) ?? listedType,
      summary: description.slice(0, 1_200),
      description,
      applyUrl,
      sourcePostedText,
      publishedAt,
      validThrough,
    };
  } catch {
    return null;
  }
};

const crawlFastenalCareers = async (source: CrawlSource, fetcher: typeof fetch): Promise<SourceCrawlResult> => {
  let responseStatus: number | null = null;
  let failureStatus: number | null = null;
  try {
    const corporateResponse = await fetchWithTimeout(fetcher, FASTENAL_CORPORATE_CAREERS_URL, {
      headers: { accept: "text/html,application/xhtml+xml" },
    }, true, { attempts: 1, timeoutMs: 8_000 });
    responseStatus = corporateResponse.status;
    if (!corporateResponse.ok) {
      failureStatus = corporateResponse.status;
      throw new Error(`Fastenal corporate careers returned HTTP ${corporateResponse.status}.`);
    }
    const corporateFinal = new URL(corporateResponse.url || FASTENAL_CORPORATE_CAREERS_URL);
    if (corporateFinal.origin !== "https://careers.fastenal.com" || corporateFinal.pathname !== "/"
      || corporateFinal.search || corporateFinal.hash || corporateFinal.username || corporateFinal.password || corporateFinal.port) {
      throw new Error("Fastenal corporate careers redirected outside its verified page.");
    }
    const corporateHtml = await corporateResponse.text();
    const verifiedSearchLink = anchorsFromHtml(corporateHtml).some(({ href, text }) => {
      try {
        const url = new URL(href, FASTENAL_CORPORATE_CAREERS_URL);
        return /^search careers$/i.test(text) && url.href === FASTENAL_JOB_SEARCH_URL;
      } catch {
        return false;
      }
    });
    if (!verifiedSearchLink) throw new Error("Fastenal corporate careers did not expose its verified job search.");

    const listingResponse = await fetchWithTimeout(fetcher, FASTENAL_JOB_SEARCH_URL, {
      headers: { accept: "text/html,application/xhtml+xml", referer: FASTENAL_CORPORATE_CAREERS_URL },
    }, true, { attempts: 1, timeoutMs: 8_000 });
    responseStatus = listingResponse.status;
    if (!listingResponse.ok) {
      failureStatus = listingResponse.status;
      throw new Error(`Fastenal job search returned HTTP ${listingResponse.status}.`);
    }
    const listingFinal = new URL(listingResponse.url || FASTENAL_JOB_SEARCH_URL);
    if (listingFinal.origin !== "https://jobs.fastenal.com" || listingFinal.pathname !== "/jobs"
      || listingFinal.search || listingFinal.hash || listingFinal.username || listingFinal.password || listingFinal.port) {
      throw new Error("Fastenal job search redirected outside its verified page.");
    }
    const sessionCookie = fastenalSessionCookie(listingResponse.headers);
    const listingHtml = await listingResponse.text();
    const csrfHeader = fastenalMetaContent(listingHtml, "_csrf_header");
    const csrfToken = fastenalMetaContent(listingHtml, "_csrf");
    const hasUsFilter = new RegExp(
      `<option\\b(?=[^>]*\\bvalue=["']${FASTENAL_US_COUNTRY_LOCALITY_ID}["'])[^>]*>\\s*United States\\s*</option>`,
      "i",
    ).test(listingHtml);
    if (csrfHeader !== "X-CSRF-TOKEN" || !csrfToken || !/^[a-z0-9-]{20,128}$/i.test(csrfToken)
      || !sessionCookie || !hasUsFilter || !/<form\b[^>]*\bid=["']findJobsForm["']/i.test(listingHtml)) {
      throw new Error("Fastenal job search returned invalid session or U.S. filter configuration.");
    }

    const searchResponse = await fetchWithTimeout(fetcher, FASTENAL_JOB_SEARCH_API_URL, {
      method: "POST",
      headers: {
        accept: "application/json",
        "content-type": "application/x-www-form-urlencoded; charset=UTF-8",
        [csrfHeader]: csrfToken,
        cookie: sessionCookie,
        referer: FASTENAL_JOB_SEARCH_URL,
        "x-requested-with": "XMLHttpRequest",
      },
      body: fastenalSearchBody(),
    }, true, { attempts: 1, timeoutMs: 10_000 });
    responseStatus = searchResponse.status;
    if (!searchResponse.ok) {
      failureStatus = searchResponse.status;
      throw new Error(`Fastenal U.S. job API returned HTTP ${searchResponse.status}.`);
    }
    if (searchResponse.url) {
      const apiFinal = new URL(searchResponse.url);
      if (apiFinal.origin !== "https://jobs.fastenal.com" || apiFinal.pathname !== "/load-jobs"
        || apiFinal.search || apiFinal.hash || apiFinal.username || apiFinal.password || apiFinal.port) {
        throw new Error("Fastenal U.S. job API redirected outside its verified endpoint.");
      }
    }
    const payload = await searchResponse.json() as FastenalListingPayload;
    const total = Number(payload.recordsTotal);
    const filtered = Number(payload.recordsFiltered);
    const rawJobs = Array.isArray(payload.data) ? payload.data as FastenalListingJob[] : null;
    if (Number(payload.draw) !== 1 || !Number.isSafeInteger(total) || !Number.isSafeInteger(filtered)
      || total < 1 || total > 1_000 || filtered < 1 || filtered > total || !rawJobs || rawJobs.length !== filtered) {
      throw new Error("Fastenal U.S. job API returned invalid catalog metadata.");
    }
    const jobs = rawJobs.flatMap((raw): CrawledJob[] => {
      const normalized = raw && typeof raw === "object" ? fastenalListingJob(raw, source) : null;
      return normalized ? [normalized] : [];
    });
    if (jobs.length !== rawJobs.length || new Set(jobs.map(({ externalId }) => externalId)).size !== jobs.length
      || new Set(jobs.map(({ officialUrl }) => officialUrl)).size !== jobs.length) {
      throw new Error("Fastenal U.S. job API returned duplicate or invalid jobs.");
    }
    const detailIndexes = jobs.flatMap((job, index) => classifyJobPrograms(job.title).keys.length > 0 ? [index] : [])
      .slice(0, 47);
    const detailResults = await Promise.all(detailIndexes.map((index) => fastenalDetailJob(
      jobs[index], source, fetcher, sessionCookie,
    )));
    for (const [offset, detail] of detailResults.entries()) if (detail) jobs[detailIndexes[offset]] = detail;
    return {
      status: "succeeded",
      responseStatus: searchResponse.status,
      completeListing: true,
      jobs,
      resolvedListingUrl: FASTENAL_JOB_SEARCH_URL,
      error: null,
    };
  } catch (error) {
    return {
      status: isBlockedHttpStatus(failureStatus ?? responseStatus) ? "blocked" : "failed",
      responseStatus: failureStatus ?? responseStatus,
      completeListing: false,
      jobs: [],
      resolvedListingUrl: FASTENAL_JOB_SEARCH_URL,
      error: error instanceof Error ? error.message : "Unknown Fastenal careers crawler error.",
    };
  }
};

const pcaCareerSearchApiUrl = (page: number): string => {
  const url = new URL(PCA_CAREER_SEARCH_API_URL);
  for (const [key, value] of [
    ["ajax", "1"], ["keyword", ""], ["title", ""], ["location", ""], ["job_type", ""], ["spage", String(page)],
  ]) url.searchParams.set(key, value);
  return url.href;
};

const pcaCareerSearchApiIdentity = (value: string, page: number): boolean => {
  try {
    const url = new URL(value);
    const expected = new URL(pcaCareerSearchApiUrl(page));
    return url.origin === expected.origin && url.pathname === expected.pathname
      && !url.username && !url.password && !url.port && !url.hash
      && url.searchParams.size === expected.searchParams.size
      && [...expected.searchParams].every(([key, expectedValue]) => url.searchParams.get(key) === expectedValue);
  } catch {
    return false;
  }
};

const pcaListingJob = (html: string, source: CrawlSource): CrawledJob | null => {
  const externalId = icimsText(html.match(/<td\b[^>]*class=["'][^"']*\bid\b[^"']*["'][^>]*>([\s\S]*?)<\/td>/i)?.[1]);
  const title = icimsText(html.match(/<td\b[^>]*class=["'][^"']*\btitle\b[^"']*["'][^>]*>([\s\S]*?)<\/td>/i)?.[1]);
  const location = icimsText(html.match(/<td\b[^>]*class=["'][^"']*\blocation\b[^"']*["'][^>]*>([\s\S]*?)<\/td>/i)?.[1]);
  const sourcePostedText = icimsText(html.match(/<td\b[^>]*class=["'][^"']*\bposted\b[^"']*["'][^>]*>([\s\S]*?)<\/td>/i)?.[1]);
  const anchor = anchorsFromHtml(html).find(({ text }) => /^view job$/i.test(text));
  const locationMatch = location?.match(/^(.+),\s*([A-Z]{2})$/);
  if (!externalId || !/^\d{4,8}$/.test(externalId) || !title || !locationMatch || !sourcePostedText
    || !/^\d{2}\/\d{2}\/\d{2}$/.test(sourcePostedText) || !anchor) return null;
  let officialUrl: URL;
  try {
    officialUrl = new URL(anchor.href, PCA_CAREER_SEARCH_URL);
  } catch {
    return null;
  }
  const pathIdentity = officialUrl.pathname.match(/^\/career-search\/posting\/[^/]+\/(\d{4,8})\/?$/i)?.[1];
  if (officialUrl.origin !== "https://careers.packagingcorp.com" || pathIdentity !== externalId
    || officialUrl.username || officialUrl.password || officialUrl.port || officialUrl.search || officialUrl.hash) return null;
  officialUrl.pathname = officialUrl.pathname.replace(/\/$/, "");
  const programs = classifyJobPrograms(title).keys;
  return {
    externalId,
    requisitionId: externalId,
    title,
    company: source.company,
    location,
    locationCity: locationMatch[1].trim(),
    locationState: locationMatch[2],
    locationCountry: "United States",
    arrangement: /\bremote\b/i.test(`${title} ${location}`) ? "remote" : "unknown",
    employmentType: programs.includes("coop") ? "Co-op"
      : programs.includes("internship") ? "Internship" : null,
    summary: null,
    sourcePostedText,
    publishedAt: normalizedUsDate(sourcePostedText),
    officialUrl: officialUrl.href,
  };
};

const pcaPage = (
  payload: PcaCareerPagePayload,
  page: number,
  source: CrawlSource,
  expectedTotal?: number,
): { total: number; jobs: CrawledJob[] } | null => {
  if (typeof payload.postings !== "string" || typeof payload.showingCount !== "string"
    || typeof payload.pagination !== "string") return null;
  const countText = icimsText(payload.showingCount);
  const count = countText?.match(/^Showing\s+(\d+)\s*[–-]\s*(\d+)\s+of\s+([\d,]+)$/i);
  if (!count) return null;
  const start = Number(count[1]);
  const end = Number(count[2]);
  const total = Number(count[3].replaceAll(",", ""));
  const expectedStart = (page - 1) * 10 + 1;
  const expectedRows = Math.min(10, total - expectedStart + 1);
  if (!Number.isSafeInteger(total) || total < 1 || total > 1_000 || expectedRows < 1
    || start !== expectedStart || end !== expectedStart + expectedRows - 1
    || (expectedTotal !== undefined && total !== expectedTotal)) return null;
  const rows = [...payload.postings.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)];
  const jobs = rows.flatMap((row) => pcaListingJob(row[0], source) ?? []);
  return rows.length === expectedRows && jobs.length === rows.length ? { total, jobs } : null;
};

const pcaDetailJob = async (
  job: CrawledJob,
  source: CrawlSource,
  fetcher: typeof fetch,
): Promise<CrawledJob | null> => {
  try {
    const response = await fetchWithTimeout(fetcher, job.officialUrl, {
      headers: { accept: "text/html,application/xhtml+xml", referer: PCA_CAREER_SEARCH_URL },
    }, true, { attempts: 1, timeoutMs: 8_000 });
    if (!response.ok) return null;
    const expected = new URL(job.officialUrl);
    const finalUrl = new URL(response.url || job.officialUrl);
    if (finalUrl.origin !== expected.origin || finalUrl.pathname.replace(/\/$/, "") !== expected.pathname.replace(/\/$/, "")
      || finalUrl.search || finalUrl.hash || finalUrl.username || finalUrl.password) return null;
    const html = await response.text();
    const title = icimsText(html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)?.[1]);
    const externalId = icimsText(html.match(/<div\b[^>]*class=["'][^"']*\bjob-id\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i)?.[1])
      ?.match(/^Req\s*#(\d{4,8})$/i)?.[1] ?? null;
    const posted = icimsText(html.match(/<div\b[^>]*class=["'][^"']*\bjob-posted\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i)?.[1])
      ?.match(/^Posted:\s*(\d{2}\/\d{2}\/\d{2})$/i)?.[1] ?? null;
    const location = icimsText(html.match(/<div\b[^>]*class=["'][^"']*\bjob-location\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i)?.[1]);
    const descriptionStart = html.search(/<div\b[^>]*class=["'][^"']*\bjob-description\b[^"']*["'][^>]*>/i);
    const descriptionEnd = descriptionStart >= 0 ? html.indexOf("</section>", descriptionStart) : -1;
    const description = descriptionStart >= 0 && descriptionEnd > descriptionStart
      ? icimsText(html.slice(descriptionStart, descriptionEnd)) : null;
    const applyUrl = anchorsFromHtml(html).flatMap(({ href, text }) => {
      if (!/^apply to job$/i.test(text)) return [];
      try {
        const url = new URL(href, job.officialUrl);
        return url.origin === "https://jobs.dayforcehcm.com"
          && /^\/en-US\/pca\/CANDIDATEPORTAL\/jobs\/\d+\/apply$/i.test(url.pathname)
          && !url.username && !url.password && !url.port && !url.hash
          && url.searchParams.size === 1 && url.searchParams.get("flowSelection") === "true" ? [url.href] : [];
      } catch {
        return [];
      }
    }).at(0) ?? null;
    if (!title || jobIdentityText(title) !== jobIdentityText(job.title) || externalId !== job.externalId
      || posted !== job.sourcePostedText || location !== job.location || !description || description.length < 100 || !applyUrl) return null;
    const coOpDetail = /\bco[- ]?op\s+(?:student|housing|assignment)\b/i.test(description);
    const salaryText = icimsText(html.match(/<div\b[^>]*class=["'][^"']*\bsalary\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i)?.[1]);
    const salary = salaryText?.match(/\$\s*([\d,]+(?:\.\d+)?)\s*[–—-]\s*\$\s*([\d,]+(?:\.\d+)?)\s+per\s+(hour|year)/i);
    return {
      ...job,
      company: source.company,
      employmentType: coOpDetail ? "Co-op" : job.employmentType,
      summary: description.slice(0, 1_200),
      description,
      applyUrl,
      ...(salary ? {
        salaryMin: Number(salary[1].replaceAll(",", "")),
        salaryMax: Number(salary[2].replaceAll(",", "")),
        salaryCurrency: "USD",
        salaryInterval: salary[3].toLocaleLowerCase(),
      } : {}),
    };
  } catch {
    return null;
  }
};

const crawlPcaCareerSearch = async (source: CrawlSource, fetcher: typeof fetch): Promise<SourceCrawlResult> => {
  let responseStatus: number | null = null;
  let failureStatus: number | null = null;
  try {
    const listingResponse = await fetchWithTimeout(fetcher, PCA_CAREER_SEARCH_URL, {
      headers: { accept: "text/html,application/xhtml+xml" },
    }, true, { attempts: 1, timeoutMs: 10_000 });
    responseStatus = listingResponse.status;
    if (!listingResponse.ok) {
      failureStatus = listingResponse.status;
      throw new Error(`Packaging Corporation careers returned HTTP ${listingResponse.status}.`);
    }
    const listingFinal = new URL(listingResponse.url || PCA_CAREER_SEARCH_URL);
    if (listingFinal.origin !== "https://careers.packagingcorp.com" || listingFinal.pathname !== "/career-search/"
      || listingFinal.search || listingFinal.hash || listingFinal.username || listingFinal.password) {
      throw new Error("Packaging Corporation careers redirected outside its verified search page.");
    }
    const listingHtml = await listingResponse.text();
    if (!new RegExp(`<input\\b(?=[^>]*\\bid=["']template-url["'])(?=[^>]*\\bvalue=["']https://careers\\.packagingcorp\\.com/wp-content/themes/pcoa["'])[^>]*>`, "i").test(listingHtml)
      || !/<th\b[^>]*class=["']id["'][^>]*>\s*JOB ID\s*<\/th>/i.test(listingHtml)
      || !/<th\b[^>]*class=["']posted["'][^>]*>\s*POSTED DATE\s*<\/th>/i.test(listingHtml)) {
      throw new Error("Packaging Corporation careers returned invalid search configuration.");
    }

    const fetchPage = async (page: number): Promise<{ payload: PcaCareerPagePayload; status: number }> => {
      const url = pcaCareerSearchApiUrl(page);
      const response = await fetchWithTimeout(fetcher, url, {
        headers: { accept: "application/json,text/plain;q=0.9", referer: PCA_CAREER_SEARCH_URL },
      }, true, { attempts: 1, timeoutMs: 8_000 });
      responseStatus = response.status;
      if (!response.ok) {
        failureStatus = response.status;
        throw new Error(`Packaging Corporation job search returned HTTP ${response.status}.`);
      }
      if (response.url && !pcaCareerSearchApiIdentity(response.url, page)) {
        throw new Error("Packaging Corporation job search redirected outside its verified endpoint.");
      }
      return { payload: await response.json() as PcaCareerPagePayload, status: response.status };
    };

    const firstResponse = await fetchPage(1);
    const first = pcaPage(firstResponse.payload, 1, source);
    if (!first) throw new Error("Packaging Corporation job search returned an invalid first page.");
    const totalPages = Math.ceil(first.total / 10);
    if (totalPages < 1 || totalPages > 100) throw new Error("Packaging Corporation job search exceeded its bounded catalog size.");
    const pages = new Map<number, CrawledJob[]>([[1, first.jobs]]);
    for (let start = 2; start <= totalPages; start += 6) {
      const pageNumbers = Array.from({ length: Math.min(6, totalPages - start + 1) }, (_, index) => start + index);
      const responses = await Promise.all(pageNumbers.map(async (page) => ({ page, response: await fetchPage(page) })));
      for (const { page, response } of responses) {
        const parsed = pcaPage(response.payload, page, source, first.total);
        if (!parsed) throw new Error("Packaging Corporation job search returned an invalid catalog page.");
        pages.set(page, parsed.jobs);
      }
    }
    const finalFirst = pcaPage((await fetchPage(1)).payload, 1, source, first.total);
    if (!finalFirst || finalFirst.jobs.map(({ officialUrl }) => officialUrl).join("|")
      !== first.jobs.map(({ officialUrl }) => officialUrl).join("|")) {
      throw new Error("Packaging Corporation job search changed during pagination.");
    }
    const catalogRows = Array.from({ length: totalPages }, (_, index) => pages.get(index + 1) ?? []).flat();
    if (catalogRows.length !== first.total) {
      throw new Error("Packaging Corporation job search returned duplicate or missing jobs.");
    }
    const grouped = new Map<string, CrawledJob[]>();
    for (const job of catalogRows) {
      const key = `${job.externalId}\u0000${job.officialUrl}`;
      grouped.set(key, [...(grouped.get(key) ?? []), job]);
    }
    const jobs: CrawledJob[] = [...grouped.values()].map((rows): CrawledJob => {
      const primary = rows[0]!;
      const alternates = rows.slice(1);
      const samePosting = rows.every((job) => job.externalId === primary.externalId
        && job.officialUrl === primary.officialUrl
        && jobIdentityText(job.title) === jobIdentityText(primary.title)
        && job.sourcePostedText === primary.sourcePostedText);
      const locations = rows.map((job) => job.location).filter((value): value is string => Boolean(value));
      if (!samePosting || new Set(locations).size !== rows.length) {
        throw new Error("Packaging Corporation job search returned duplicate or conflicting jobs.");
      }
      return {
        ...primary,
        secondaryLocations: [...new Set([
          ...(primary.secondaryLocations ?? []),
          ...alternates.flatMap((job) => [job.location, ...(job.secondaryLocations ?? [])]),
        ].filter((value): value is string => Boolean(value) && value !== primary.location))],
      };
    });
    const detailBudget = Math.max(0, 50 - (totalPages + 2));
    const detailIndexes = jobs.flatMap((job, index) => classifyJobPrograms(job.title).keys.length > 0 ? [index] : [])
      .slice(0, detailBudget);
    const detailResults = await Promise.all(detailIndexes.map((index) => pcaDetailJob(jobs[index], source, fetcher)));
    for (const [offset, detail] of detailResults.entries()) if (detail) jobs[detailIndexes[offset]] = detail;
    return {
      status: "succeeded",
      responseStatus: firstResponse.status,
      completeListing: true,
      jobs,
      resolvedListingUrl: PCA_CAREER_SEARCH_URL,
      error: null,
    };
  } catch (error) {
    return {
      status: isBlockedHttpStatus(failureStatus ?? responseStatus) ? "blocked" : "failed",
      responseStatus: failureStatus ?? responseStatus,
      completeListing: false,
      jobs: [],
      resolvedListingUrl: PCA_CAREER_SEARCH_URL,
      error: error instanceof Error ? error.message : "Unknown Packaging Corporation crawler error.",
    };
  }
};

