type WorkdayDetailPayload = {
  jobPostingInfo?: {
    title?: unknown;
    jobReqId?: unknown;
    startDate?: unknown;
    timeType?: unknown;
    location?: unknown;
    additionalLocations?: unknown;
    jobDescription?: unknown;
  };
};

const workdayDetailCandidates = (jobUrl: string): string[] => {
  let url: URL;
  try {
    url = new URL(jobUrl);
  } catch {
    return [];
  }
  const tenantMatch = url.hostname.match(/^([^.]+)\.wd\d+\.myworkdayjobs\.com$/i);
  if (!tenantMatch) return [];
  const segments = url.pathname.split("/").filter(Boolean);
  const jobIndex = segments.findIndex((segment) => segment.toLocaleLowerCase() === "job");
  if (jobIndex < 0 || jobIndex === segments.length - 1) return [];
  const explicitSite = jobIndex > 0 && !/^[a-z]{2}-[A-Z]{2}$/.test(segments[jobIndex - 1])
    ? segments[jobIndex - 1]
    : null;
  const sites = [...new Set([explicitSite, "External", "Careers"].filter((site): site is string => Boolean(site)))];
  const detailSegments = segments.slice(jobIndex + 1);
  if (detailSegments.at(-1)?.toLocaleLowerCase() === "apply") detailSegments.pop();
  if (detailSegments.length === 0) return [];
  const suffix = detailSegments.map(encodeURIComponent).join("/");
  const tenants = [...new Set([tenantMatch[1], tenantMatch[1].replaceAll("-", "_")])];
  return tenants.flatMap((tenant) => sites.map((site) => new URL(
    `/wday/cxs/${encodeURIComponent(tenant)}/${encodeURIComponent(site)}/job/${suffix}`,
    url.origin,
  ).href));
};

const smartRecruitersDetailEndpoint = (job: CrawledJob): { companyCode: string; endpoint: string } | null => {
  try {
    const url = new URL(job.officialUrl);
    const companyCode = decodeURIComponent(url.pathname.split("/").filter(Boolean)[0] ?? "");
    const externalId = job.externalId?.trim() ?? "";
    if (url.protocol !== "https:" || url.hostname.toLocaleLowerCase() !== "jobs.smartrecruiters.com"
      || !/^[a-z0-9_-]+$/i.test(companyCode) || !/^[a-z0-9-]+$/i.test(externalId)) return null;
    return {
      companyCode,
      endpoint: `https://api.smartrecruiters.com/v1/companies/${encodeURIComponent(companyCode)}/postings/${encodeURIComponent(externalId)}`,
    };
  } catch {
    return null;
  }
};

const verifiedSmartRecruitersApplyUrl = (value: string | undefined, companyCode: string, externalId: string): string | null => {
  if (!value) return null;
  try {
    const url = new URL(value);
    const path = url.pathname.split("/").filter(Boolean).map(decodeURIComponent);
    return url.protocol === "https:" && url.hostname.toLocaleLowerCase() === "jobs.smartrecruiters.com"
      && path[0]?.toLocaleLowerCase() === companyCode.toLocaleLowerCase()
      && path[1]?.toLocaleLowerCase().startsWith(externalId.toLocaleLowerCase())
      ? url.href
      : null;
  } catch {
    return null;
  }
};

const combinedEmploymentType = (job: CrawledJob, timeType: unknown): string | null => {
  const values: string[] = [];
  const add = (value: string | null | undefined) => {
    const trimmed = value?.trim();
    if (trimmed && !values.some((existing) => existing.toLocaleLowerCase() === trimmed.toLocaleLowerCase())) values.push(trimmed);
  };
  const programs = classifyJobPrograms(job.title);
  if (programs.keys.length > 0 || normalizeEmploymentType(job.employmentType)?.split(" / ").includes("Internship")) add("Internship");
  add(asText(timeType));
  if (values.length === 0) add(job.employmentType);
  return values.join("; ") || null;
};

const jobIdentityText = (value: string | null | undefined): string => (value ?? "")
  .normalize("NFKD")
  .replace(/\p{M}+/gu, "")
  .toLocaleLowerCase()
  .replace(/[^a-z0-9]+/g, " ")
  .trim();

const mergeProgramJobDetail = (
  job: CrawledJob,
  detail: Partial<CrawledJob>,
  applyUrl?: string | null,
): CrawledJob => ({
  ...job,
  location: detail.location ?? job.location,
  arrangement: detail.arrangement && detail.arrangement !== "unknown" ? detail.arrangement : job.arrangement,
  employmentType: combinedEmploymentType(job, detail.employmentType),
  summary: detail.summary ?? job.summary,
  description: detail.description ?? job.description ?? null,
  responsibilities: detail.responsibilities ?? job.responsibilities ?? null,
  qualifications: detail.qualifications ?? job.qualifications ?? null,
  skills: detail.skills?.length ? detail.skills : job.skills,
  department: detail.department ?? job.department,
  team: detail.team ?? job.team,
  businessUnit: detail.businessUnit ?? job.businessUnit,
  jobFamily: detail.jobFamily ?? job.jobFamily,
  jobFunction: detail.jobFunction ?? job.jobFunction,
  industry: detail.industry ?? job.industry,
  office: detail.office ?? job.office,
  secondaryLocations: detail.secondaryLocations?.length ? detail.secondaryLocations : job.secondaryLocations,
  locationCity: detail.locationCity ?? job.locationCity,
  locationState: detail.locationState ?? job.locationState,
  locationCountry: detail.locationCountry ?? job.locationCountry,
  locationPostalCode: detail.locationPostalCode ?? job.locationPostalCode,
  latitude: detail.latitude ?? job.latitude,
  longitude: detail.longitude ?? job.longitude,
  salaryMin: detail.salaryMin ?? job.salaryMin,
  salaryMax: detail.salaryMax ?? job.salaryMax,
  salaryCurrency: detail.salaryCurrency ?? job.salaryCurrency,
  salaryInterval: detail.salaryInterval ?? job.salaryInterval,
  benefits: detail.benefits ?? job.benefits,
  educationRequirements: detail.educationRequirements ?? job.educationRequirements,
  experienceRequirements: detail.experienceRequirements ?? job.experienceRequirements,
  experienceLevel: detail.experienceLevel ?? job.experienceLevel,
  shiftSchedule: detail.shiftSchedule ?? job.shiftSchedule,
  travelRequirements: detail.travelRequirements ?? job.travelRequirements,
  securityClearance: detail.securityClearance ?? job.securityClearance,
  languages: detail.languages?.length ? detail.languages : job.languages,
  requisitionId: detail.requisitionId ?? detail.externalId ?? job.requisitionId ?? job.externalId,
  applyUrl: applyUrl ?? detail.applyUrl ?? job.applyUrl,
  sourcePostedText: detail.sourcePostedText ?? job.sourcePostedText,
  sourceUpdatedAt: detail.sourceUpdatedAt ?? job.sourceUpdatedAt,
  validThrough: detail.validThrough ?? job.validThrough,
  publishedAt: detail.publishedAt ?? job.publishedAt,
  // The listing URL is the stable deduplication key. Detail enrichment may
  // resolve an ATS apply URL, but must never replace the canonical job URL.
  officialUrl: job.officialUrl,
});

const matchingJsonLdDetail = (html: string, source: CrawlSource, job: CrawledJob): CrawledJob | null => {
  const details = jsonLdScripts(html).flatMap(jobPostingNodes)
    .map((node) => jsonLdJob(node, source))
    .filter((detail): detail is CrawledJob => detail !== null);
  const externalIdentity = job.requisitionId ?? job.externalId;
  return details.find((detail) => Boolean(
    externalIdentity && (detail.requisitionId === externalIdentity || detail.externalId === externalIdentity),
  )) ?? details.find((detail) => jobIdentityText(detail.title) === jobIdentityText(job.title)) ?? null;
};

const officialApplyUrl = (html: string, pageUrl: string): string | null => anchorsFromHtml(html)
  .flatMap(({ href, text }) => {
    try {
      const url = new URL(href, pageUrl);
      if (!/^https:$/.test(url.protocol)) return [];
      const isWorkdayApply = /\.myworkdayjobs\.com$/i.test(url.hostname) && /\/apply\/?$/i.test(url.pathname);
      const isExplicitApply = url.origin === new URL(pageUrl).origin
        && /\bapply(?: now| externally)?\b/i.test(text)
        && /\b(?:job|career|apply)\b/i.test(url.href);
      return isWorkdayApply || isExplicitApply ? [url.href] : [];
    } catch {
      return [];
    }
  })
  .at(0) ?? null;

const verifiedInactiveCareerPage = (
  source: CrawlSource,
  finalPage: URL,
  html: string,
): { resolvedListingUrl: string } | null => {
  if (source.id === "p5-0715-replicate"
    && finalPage.origin === "https://replicate.com"
    && /^\/about\/?$/i.test(finalPage.pathname)
    && /<title[^>]*>\s*About\s*(?:&amp;|&)\s*Careers\s*[–-]\s*Replicate\s*<\/title>/i.test(html)
    && /<section\b[^>]*\bid=["']join-us["'][^>]*>[\s\S]*?href=["']https:\/\/www\.cloudflare\.com\/careers\/?["']/i.test(html)
    && /Find our available positions on the/i.test(plainText(html) ?? "")) {
    return { resolvedListingUrl: "https://replicate.com/about" };
  }

  if (source.id === "p4-0440-groq"
    && finalPage.origin === "https://groq.com"
    && /^\/company\/?$/i.test(finalPage.pathname)
    && /<title[^>]*>\s*Company\s*\|\s*Groq\b/i.test(html)
    && !/\bOpen Positions\b|\bGroq Internships\b|job-boards\.greenhouse\.io\/groq|boards-api\.greenhouse\.io\/v1\/boards\/groq|jobs\.ashbyhq\.com|jobs\.lever\.co/i.test(html)
    && !anchorsFromHtml(html).some(({ href, text }) => /(?:^|\/)careers?(?:[/?#]|$)|(?:^|\/)jobs?(?:[/?#]|$)|\b(?:open positions|view jobs|join our team)\b/i.test(`${href} ${text}`))) {
    return { resolvedListingUrl: "https://groq.com/company" };
  }

  return null;
};

// Only hosts verified to publish trustworthy JobPosting JSON-LD belong here.
// Keeping this explicit avoids spending one detail request on every internship
// returned by already-rich ATS feeds.
const VERIFIED_JSON_LD_DETAIL_HOSTS = new Set([
  "careers.fedex.com",
  "jobs.citi.com",
  "search.jobs.barclays",
]);

const supportsJsonLdDetailEnrichment = (jobUrl: string): boolean => {
  try {
    return VERIFIED_JSON_LD_DETAIL_HOSTS.has(new URL(jobUrl).hostname.toLocaleLowerCase());
  } catch {
    return false;
  }
};

const standardCharteredDetail = (
  html: string,
  source: CrawlSource,
  job: CrawledJob,
  responseUrl: string,
): { detail: CrawledJob; applyUrl: string | null } | null => {
  let expected: URL;
  let finalPage: URL;
  try {
    expected = new URL(job.officialUrl);
    finalPage = new URL(responseUrl || job.officialUrl);
  } catch {
    return null;
  }
  if (expected.hostname.toLocaleLowerCase() !== "jobs.standardchartered.com"
    || finalPage.origin !== expected.origin) return null;

  const tokenHtml = (label: string): string | null => html.match(new RegExp(
    `<span\\b[^>]*class=["'][^"']*\\bjoblayouttoken-label\\b[^"']*["'][^>]*>\\s*${label}:?[^<]*<\\/span>\\s*<span\\b[^>]*>([\\s\\S]*?)<\\/span>`,
    "i",
  ))?.[1] ?? null;
  const title = plainText(html.match(/<span\b[^>]*itemprop=["']title["'][^>]*>([\s\S]*?)<\/span>/i)?.[1]);
  const requisitionId = plainText(tokenHtml("Requisition Number"));
  if (!title || !requisitionId || requisitionId !== job.externalId
    || jobIdentityText(title) !== jobIdentityText(job.title)
    || !finalPage.pathname.split("/").some((segment) => segment.startsWith(`${requisitionId}-`))) return null;

  const location = plainText(tokenHtml("Job Location \\(Short\\)")) ?? job.location;
  const workType = plainText(tokenHtml("Work Type"));
  const employmentType = plainText(tokenHtml("Employment Type"));
  const postedText = plainText(tokenHtml("Posting Start Date"));
  const validThroughText = plainText(tokenHtml("Posting End Date"));
  const descriptionOpening = html.match(/<span\b[^>]*itemprop=["']description["'][^>]*>/i);
  const descriptionStart = descriptionOpening?.index == null
    ? -1
    : descriptionOpening.index + descriptionOpening[0].length;
  const relativeApplyStart = descriptionStart >= 0
    ? html.slice(descriptionStart).search(/<div\b[^>]*class=["'][^"']*\bapplylink\b/i)
    : -1;
  const applyStart = relativeApplyStart >= 0 ? descriptionStart + relativeApplyStart : -1;
  const descriptionRegion = descriptionStart >= 0 && applyStart > descriptionStart
    ? html.slice(descriptionStart, applyStart)
    : null;
  const outerDescriptionEnd = descriptionRegion?.toLocaleLowerCase().lastIndexOf("</span>") ?? -1;
  const description = plainText(outerDescriptionEnd >= 0
    ? descriptionRegion!.slice(0, outerDescriptionEnd)
    : tokenHtml("Job Description"));
  const arrangement = /\bremote\b/i.test(`${location ?? ""} ${workType ?? ""}`)
    ? "remote"
    : /\bhybrid\b/i.test(workType ?? "")
      ? "hybrid"
      : /\b(?:office|on-?site)\b/i.test(workType ?? "") ? "onsite" : "unknown";
  return {
    detail: {
      externalId: requisitionId,
      requisitionId,
      title,
      company: source.company,
      location,
      arrangement,
      employmentType,
      summary: description,
      description,
      officialUrl: job.officialUrl,
      sourcePostedText: postedText,
      publishedAt: successFactorsDate(postedText),
      validThrough: successFactorsDate(validThroughText),
    },
    applyUrl: officialApplyUrl(html, finalPage.href),
  };
};

const barclaysReaderDetail = (
  markdown: string,
  source: CrawlSource,
  job: CrawledJob,
): { detail: CrawledJob; applyUrl: string | null } | null => {
  let sourceUrl: URL;
  let jobUrl: URL;
  try {
    const sourceText = markdown.match(/^[ \t]*URL Source:\s*(\S+)\s*$/im)?.[1];
    if (!sourceText) return null;
    sourceUrl = new URL(sourceText);
    jobUrl = new URL(job.officialUrl);
  } catch {
    return null;
  }
  if (sourceUrl.hostname.toLocaleLowerCase() !== "search.jobs.barclays"
    || jobUrl.hostname.toLocaleLowerCase() !== "search.jobs.barclays"
    || sourceUrl.pathname.replace(/\/$/, "") !== jobUrl.pathname.replace(/\/$/, "")) return null;

  const readerTitle = markdown.match(/^[ \t]*Title:\s*(.+?)\s+at Barclays\s*$/im)?.[1]?.trim();
  if (!readerTitle || jobIdentityText(readerTitle) !== jobIdentityText(job.title)) return null;
  const externalId = jobUrl.pathname.split("/").filter(Boolean).at(-1) ?? null;
  if (!externalId || externalId !== job.externalId) return null;

  const requisitionId = markdown.match(/\bReference Code:\s*(JR-[0-9]+)\b/i)?.[1] ?? null;
  const dateLive = markdown.match(/\bDate live:\s*(\d{1,2}\/\d{1,2}\/\d{4})\b/i)?.[1] ?? null;
  const contract = markdown.match(/\bContract:\s*([^\n]+)/i)?.[1]?.replace(/[*_`]/g, "").trim() ?? null;
  const location = markdown.match(/Markdown Content:\s*\n+([^\n#][^\n]*)/i)?.[1]?.trim() ?? job.location;
  const descriptionSection = markdown.split(/^[ \t]*##\s+Job description\s*$/im)[1]
    ?.split(/^[ \t]*Links\/Buttons:\s*$/im)[0]
    ?.trim() ?? null;
  const description = descriptionSection
    ? descriptionSection.replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1").replace(/[*_`#]+/g, " ").replace(/\s+/g, " ").trim()
    : null;
  const applyUrl = [...markdown.matchAll(/\[Apply for job\]\((https:\/\/[^)]+)\)/gi)]
    .map((match) => match[1])
    .find((value) => {
      try {
        const candidate = new URL(value);
        return candidate.hostname.toLocaleLowerCase() === "barclays.wd3.myworkdayjobs.com"
          && /\/apply\/?$/i.test(candidate.pathname)
          && Boolean(requisitionId && candidate.pathname.includes(`_${requisitionId}`));
      } catch {
        return false;
      }
    }) ?? null;

  return {
    detail: {
      externalId: requisitionId ?? externalId,
      title: readerTitle,
      company: source.company,
      location,
      arrangement: /\bremote\b/i.test(location ?? "") ? "remote" : "unknown",
      employmentType: normalizeEmploymentType(contract),
      summary: description,
      description,
      ...(requisitionId ? { requisitionId } : {}),
      officialUrl: job.officialUrl,
      publishedAt: normalizedUsDate(dateLive),
    },
    applyUrl,
  };
};

const fetchBarclaysReaderDetail = async (
  job: CrawledJob,
  source: CrawlSource,
  fetcher: typeof fetch,
): Promise<{ detail: CrawledJob; applyUrl: string | null } | null> => {
  const target = new URL(job.officialUrl);
  const httpTarget = new URL(target);
  httpTarget.protocol = "http:";
  for (const endpoint of [`https://r.jina.ai/${target.href}`, `https://r.jina.ai/${httpTarget.href}`]) {
    try {
      const response = await fetchWithTimeout(fetcher, endpoint, {
        headers: {
          accept: "text/plain",
          "user-agent": "Mozilla/5.0 (compatible; JobPulseCrawler/1.0)",
          "x-retain-links": "all",
          "x-with-links-summary": "all",
        },
      }, false, { attempts: 1, timeoutMs: 8_000 });
      if (!response.ok) continue;
      const reader = barclaysReaderDetail(await response.text(), source, job);
      if (reader) return reader;
    } catch {
      // Continue to the independent protocol-keyed reader cache.
    }
  }
  return null;
};

const pennMedicineReaderDetail = (
  markdown: string,
  source: CrawlSource,
  job: CrawledJob,
): CrawledJob | null => {
  let sourceUrl: URL;
  let jobUrl: URL;
  try {
    const sourceText = markdown.match(/^[ \t]*URL Source:\s*(\S+)\s*$/im)?.[1];
    if (!sourceText) return null;
    sourceUrl = new URL(sourceText);
    jobUrl = new URL(job.officialUrl);
  } catch {
    return null;
  }
  if (source.id !== "p5-1018-penn-medicine"
    || sourceUrl.protocol !== "https:"
    || sourceUrl.hostname.toLocaleLowerCase() !== "careers.pennmedicine.org"
    || jobUrl.hostname.toLocaleLowerCase() !== "careers.pennmedicine.org"
    || sourceUrl.pathname.replace(/\/$/, "") !== jobUrl.pathname.replace(/\/$/, "")) return null;

  const externalId = jobUrl.pathname.match(/^\/jobs\/(\d+)-[^/?#]+\/?$/i)?.[1] ?? null;
  if (!externalId || externalId !== job.externalId) return null;
  const readerTitle = markdown.match(/^[ \t]*Title:\s*(.+?)\s*$/im)?.[1]?.trim() ?? null;
  const headingTitle = markdown.match(/^[ \t]*##\s+([^\n]+?)\s*$/im)?.[1]?.trim() ?? null;
  const expectedTitle = jobIdentityText(job.title);
  const readerIdentities = [readerTitle, headingTitle].map(jobIdentityText).filter(Boolean);
  const titleMatches = readerIdentities.some((identity) =>
    identity === expectedTitle
    || identity.startsWith(`${expectedTitle} in `)
    || (identity.length >= 12 && (expectedTitle.startsWith(`${identity} `) || identity.startsWith(`${expectedTitle} `))));
  if (!expectedTitle || !titleMatches) return null;

  const requisitionId = markdown.match(/\*\*Job ID:\*\*\s*([A-Za-z0-9_-]+)/i)?.[1] ?? null;
  const category = markdown.match(/\*\*Category:\*\*\s*([^\n]+)/i)?.[1]?.trim() ?? null;
  const workType = markdown.match(/\*\*Work Type:\*\*\s*([^\n]+)/i)?.[1]?.trim() ?? null;
  const location = markdown.match(/\*\*Location:\*\*\s*([^\n]+)/i)?.[1]?.trim() ?? job.location;
  const schedule = markdown.match(/\*\*Work Schedule:\*\*\s*([^\n]+)/i)?.[1]?.trim() ?? null;
  const publishedText = markdown.match(/^[ \t]*Published Time:\s*(\S+)\s*$/im)?.[1] ?? null;
  const rawDescription = markdown.split(/^[ \t]*\*\*Description\*\*[ \t]*$/im)[1]
    ?.split(/^[ \t]*(?:\*\*Current UPHS-paid Employees|Live Your Life's Work)/im)[0]
    ?.trim() ?? null;
  const description = rawDescription
    ? rawDescription
        .replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1")
        .replace(/[*_`#]+/g, " ")
        .replace(/[ \t]+/g, " ")
        .replace(/\n{3,}/g, "\n\n")
        .trim()
    : null;
  const employmentType = normalizeEmploymentType(workType)
    ?? (/^FT\b/i.test(workType ?? "") ? "Full-time"
      : /^PT\b/i.test(workType ?? "") ? "Part-time"
        : /\bper diem\b/i.test(workType ?? "") ? "Per diem" : null);
  const arrangementText = `${location ?? ""} ${schedule ?? ""}`;
  return {
    externalId,
    title: job.title,
    company: source.company,
    location,
    arrangement: /\bremote\b/i.test(arrangementText)
      ? "remote"
      : /\bhybrid\b/i.test(arrangementText) ? "hybrid" : job.arrangement,
    employmentType,
    summary: description,
    description,
    ...(category ? { department: category } : {}),
    ...(requisitionId ? { requisitionId } : {}),
    officialUrl: job.officialUrl,
    sourcePostedText: publishedText,
    publishedAt: normalizedDate(publishedText),
  };
};

const fetchPennMedicineReaderDetail = async (
  job: CrawledJob,
  source: CrawlSource,
  fetcher: typeof fetch,
): Promise<CrawledJob | null> => {
  try {
    const target = new URL(job.officialUrl);
    const response = await fetchWithTimeout(fetcher, `https://r.jina.ai/${target.href}`, {
      headers: {
        accept: "text/plain",
        "user-agent": "Mozilla/5.0 (compatible; JobPulseCrawler/1.0)",
        "x-retain-links": "all",
      },
    }, false, { attempts: 1, timeoutMs: 8_000 });
    return response.ok ? pennMedicineReaderDetail(await response.text(), source, job) : null;
  } catch {
    return null;
  }
};

const fetchBarclaysWorkdayDetail = async (
  job: CrawledJob,
  source: CrawlSource,
  fetcher: typeof fetch,
): Promise<{ detail: CrawledJob; applyUrl: string } | null> => {
  let listing: URL;
  try {
    listing = new URL(job.officialUrl);
  } catch {
    return null;
  }
  if (listing.protocol !== "https:"
    || listing.hostname.toLocaleLowerCase() !== "search.jobs.barclays"
    || !/^\/job\/(?:[^/?#]+\/)+13015\/\d+\/?$/i.test(listing.pathname)) return null;

  const origin = "https://barclays.wd3.myworkdayjobs.com";
  const site = "External_Career_Site_Barclays";
  const searchEndpoint = `${origin}/wday/cxs/barclays/${site}/jobs`;
  try {
    const searchResponse = await fetchWithTimeout(fetcher, searchEndpoint, {
      method: "POST",
      headers: { accept: "application/json", "content-type": "application/json" },
      body: JSON.stringify({ appliedFacets: {}, limit: 20, offset: 0, searchText: job.title }),
    }, false, { attempts: 1, timeoutMs: 5_000 });
    if (!searchResponse.ok) return null;
    const search = await searchResponse.json() as WorkdayPayload;
    const exact = (search.jobPostings ?? []).filter((posting) =>
      Boolean(posting.title && posting.externalPath)
      && jobIdentityText(posting.title) === jobIdentityText(job.title));
    if (exact.length !== 1) return null;
    const externalPath = exact[0].externalPath!;
    const requisitionId = externalPath.match(/_(JR-\d+)(?:-[^/?#]+)?$/i)?.[1] ?? null;
    if (!requisitionId || !/^\/job\/(?:[^/?#]+\/)*[^/?#]+_JR-\d+(?:-[^/?#]+)?$/i.test(externalPath)) return null;

    const detailEndpoint = `${origin}/wday/cxs/barclays/${site}${externalPath}`;
    const detailResponse = await fetchWithTimeout(fetcher, detailEndpoint, {
      headers: { accept: "application/json" },
    }, false, { attempts: 1, timeoutMs: 5_000 });
    if (!detailResponse.ok) return null;
    const payload = await detailResponse.json() as WorkdayDetailPayload;
    const info = payload.jobPostingInfo;
    const detailTitle = asText(info?.title);
    const detailRequisitionId = asText(info?.jobReqId);
    if (!info || !detailTitle || detailRequisitionId !== requisitionId
      || jobIdentityText(detailTitle) !== jobIdentityText(job.title)) return null;
    const description = plainText(asText(info.jobDescription));
    const additionalLocations = Array.isArray(info.additionalLocations)
      ? info.additionalLocations.flatMap((value) => asText(value) ?? [])
      : [];
    const atsJobUrl = new URL(`/${site}${externalPath}`, origin).href;
    return {
      detail: {
        externalId: job.externalId,
        title: detailTitle,
        company: source.company,
        location: asText(info.location) ?? job.location,
        arrangement: job.arrangement,
        employmentType: asText(info.timeType),
        summary: description,
        description,
        requisitionId,
        ...(additionalLocations.length > 0 ? { secondaryLocations: additionalLocations } : {}),
        officialUrl: job.officialUrl,
        publishedAt: normalizedDate(asText(info.startDate)),
      },
      applyUrl: `${atsJobUrl.replace(/\/$/, "")}/apply`,
    };
  } catch {
    return null;
  }
};

const enrichProgramJobDetails = async (
  result: SourceCrawlResult,
  source: CrawlSource,
  fetcher: typeof fetch,
  now: Date,
): Promise<SourceCrawlResult> => {
  if (result.status !== "succeeded" || result.jobs.length === 0) return result;
  const enriched = [...result.jobs];
  const targets = result.jobs.flatMap((job, index) => {
    const indexedAsProgram = classifyJobPrograms(job.title).keys.length > 0
      || normalizeEmploymentType(job.employmentType)?.split(" / ").includes("Internship");
    const hasLocation = Boolean(job.location && !/^(?:location not specified|multiple locations)$/i.test(job.location.trim()));
    const needsDetail = !hasLocation
      || !job.description || job.description.trim().length < 100
      || !(job.requisitionId ?? job.externalId)
      || !job.publishedAt;
    if (!indexedAsProgram || !needsDetail) return [];
    const candidates = workdayDetailCandidates(job.officialUrl);
    return [{ index, candidates }];
  });
  // Catalogs are normally newest-first. Always enrich the first half of the
  // bounded detail budget so a newly published internship gets its ATS
  // requisition/apply identity during the same crawl (and can be deduplicated
  // against an ATS mirror). Rotate the remainder so older sparse records still
  // converge over subsequent two-hour passes.
  const prioritizedCount = Math.min(Math.ceil(WORKDAY_DETAIL_BATCH_SIZE / 2), targets.length);
  const prioritizedTargets = targets.slice(0, prioritizedCount);
  const rotatingTargets = targets.slice(prioritizedCount);
  const rotatingBudget = WORKDAY_DETAIL_BATCH_SIZE - prioritizedTargets.length;
  const enrichmentStart = rotatingTargets.length === 0
    ? 0
    : (Math.floor(now.getTime() / (2 * 60 * 60 * 1_000)) * Math.max(1, rotatingBudget)) % rotatingTargets.length;
  const selectedTargets = targets.length <= WORKDAY_DETAIL_BATCH_SIZE
    ? targets
    : [
        ...prioritizedTargets,
        ...Array.from(
          { length: rotatingBudget },
          (_, offset) => rotatingTargets[(enrichmentStart + offset) % rotatingTargets.length],
        ),
      ];

  const enrichOne = async ({ index, candidates }: { index: number; candidates: string[] }): Promise<void> => {
    const job = enriched[index];
    const isBarclaysDetail = (() => {
      try {
        return new URL(job.officialUrl).hostname.toLocaleLowerCase() === "search.jobs.barclays";
      } catch {
        return false;
      }
    })();
    const isPennMedicineDetail = source.id === "p5-1018-penn-medicine" && (() => {
      try {
        return new URL(job.officialUrl).hostname.toLocaleLowerCase() === "careers.pennmedicine.org";
      } catch {
        return false;
      }
    })();
    if (source.id === "p2-0039-goldman-sachs") {
      const detail = await goldmanRoleDetail(job, fetcher);
      if (detail) enriched[index] = { ...job, ...detail };
      return;
    }
    const selectMindsIdentity = selectMindsJobIdentity(job.officialUrl);
    if (selectMindsIdentity) {
      try {
        const response = await fetchWithTimeout(fetcher, selectMindsIdentity.url, undefined, true, { attempts: 1, timeoutMs: 4_000 });
        if (response.ok && (!response.url || response.url === selectMindsIdentity.url)) {
          const html = await response.text();
          const detailId = html.match(/class=["'][^"']*\bjUserRefreshJobId\b[^"']*["'][^>]*\bvalue=["'](\d+)["']/i)?.[1]
            ?? html.match(/\bvalue=["'](\d+)["'][^>]*class=["'][^"']*\bjUserRefreshJobId\b/i)?.[1];
          const title = icimsText(html.match(/<h1\b[^>]*class=["'][^"']*\btitle\b[^"']*["'][^>]*>([\s\S]*?)<\/h1>/i)?.[1]);
          if (detailId === selectMindsIdentity.id && title && jobIdentityText(title) === jobIdentityText(job.title)) {
            const descriptionStart = html.search(/<div\b[^>]*class=["'][^"']*\bjob_description\b[^"']*["'][^>]*>/i);
            const qualificationsStart = descriptionStart >= 0
              ? html.slice(descriptionStart).search(/<div\b[^>]*class=["'][^"']*\bjob_qualifications\b[^"']*["'][^>]*>/i)
              : -1;
            const absoluteQualificationsStart = qualificationsStart >= 0 ? descriptionStart + qualificationsStart : -1;
            const technicalEnd = html.indexOf("<!-- TEC-", Math.max(descriptionStart, absoluteQualificationsStart));
            const description = descriptionStart >= 0
              ? icimsText(html.slice(descriptionStart, absoluteQualificationsStart >= 0 ? absoluteQualificationsStart : technicalEnd >= 0 ? technicalEnd : html.length))
              : null;
            const qualifications = absoluteQualificationsStart >= 0
              ? icimsText(html.slice(absoluteQualificationsStart, technicalEnd >= 0 ? technicalEnd : html.length))
              : null;
            const requisitionId = icimsText(html.match(
              /<dd\b[^>]*class=["'][^"']*\bjob_external_id\b[^"']*["'][^>]*>[\s\S]*?<span\b[^>]*class=["'][^"']*\bfield_value\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i,
            )?.[1]);
            const postedText = icimsText(html.match(
              /<dd\b[^>]*class=["'][^"']*\bjob_post_date\b[^"']*["'][^>]*>[\s\S]*?<span\b[^>]*class=["'][^"']*\bfield_value\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i,
            )?.[1]);
            const relative = postedText?.match(/^(\d+)\s+(minute|hour|day|week)s?\s+ago$/i);
            const unitMs = relative ? ({ minute: 60_000, hour: 3_600_000, day: 86_400_000, week: 604_800_000 } as const)[relative[2].toLocaleLowerCase() as "minute" | "hour" | "day" | "week"] : null;
            const publishedAt = relative && unitMs
              ? new Date(now.getTime() - Number(relative[1]) * unitMs).toISOString()
              : postedText && /^yesterday$/i.test(postedText)
                ? new Date(now.getTime() - 86_400_000).toISOString()
                : postedText && /^today$/i.test(postedText) ? now.toISOString() : normalizedDate(postedText);
            enriched[index] = mergeProgramJobDetail(job, {
              title,
              summary: description ?? job.summary,
              description,
              responsibilities: description,
              qualifications,
              requisitionId,
              sourcePostedText: postedText,
              publishedAt,
            });
            return;
          }
        }
      } catch {
        // Detail enrichment is optional; the verified listing remains usable.
      }
    }
    const smartRecruitersDetail = smartRecruitersDetailEndpoint(job);
    if (smartRecruitersDetail) {
      try {
        const response = await fetchWithTimeout(fetcher, smartRecruitersDetail.endpoint, {
          headers: { accept: "application/json" },
        }, false, { attempts: 1, timeoutMs: 4_000 });
        if (response.ok) {
          const payload = await response.json() as SmartRecruitersDetailPayload;
          const validIdentity = payload.active !== false
            && payload.id === job.externalId
            && typeof payload.name === "string"
            && jobIdentityText(payload.name) === jobIdentityText(job.title)
            && (!payload.company?.identifier
              || payload.company.identifier.toLocaleLowerCase() === smartRecruitersDetail.companyCode.toLocaleLowerCase());
          if (validIdentity) {
            const base = normalizeSmartRecruitersJob(source, smartRecruitersDetail.companyCode, payload);
            const sections = payload.jobAd?.sections ?? {};
            const jobDescription = icimsText(sections.jobDescription?.text);
            const qualifications = icimsText(sections.qualifications?.text);
            const additionalInformation = icimsText(sections.additionalInformation?.text);
            const description = [jobDescription, additionalInformation].filter(Boolean).join("\n\n") || null;
            enriched[index] = mergeProgramJobDetail(job, {
              ...base,
              summary: jobDescription,
              description,
              responsibilities: jobDescription,
              qualifications,
            }, verifiedSmartRecruitersApplyUrl(payload.applyUrl, smartRecruitersDetail.companyCode, job.externalId!));
            return;
          }
        }
      } catch {
        // Detail enrichment is optional; the verified listing remains usable.
      }
    }
    for (const endpoint of candidates) {
      try {
        const response = await fetchWithTimeout(fetcher, endpoint, undefined, true, { attempts: 1, timeoutMs: 4_000 });
        if (!response.ok) continue;
        const payload = await response.json() as WorkdayDetailPayload;
        const info = payload.jobPostingInfo;
        if (!info || typeof info !== "object") continue;
        const description = plainText(asText(info.jobDescription));
        const additionalLocations = Array.isArray(info.additionalLocations)
          ? info.additionalLocations.flatMap((value) => asText(value) ?? [])
          : [];
        enriched[index] = mergeProgramJobDetail(job, {
          employmentType: asText(info.timeType),
          description,
          requisitionId: asText(info.jobReqId),
          location: asText(info.location),
          ...(additionalLocations.length > 0 ? { secondaryLocations: additionalLocations } : {}),
          publishedAt: normalizedDate(info.startDate),
        });
        return;
      } catch {
        // Detail enrichment is optional; the verified listing remains usable.
      }
    }
    if (isBarclaysDetail) {
      // TalentBrew's detail HTML and public text-reader caches are both
      // intermittently unavailable from Worker egress. Resolve the same role
      // through Barclays' first-party Workday search/detail APIs using an
      // exact title and requisition identity before falling back to HTML.
      const workdayDetail = await fetchBarclaysWorkdayDetail(job, source, fetcher);
      if (workdayDetail) {
        enriched[index] = mergeProgramJobDetail(job, workdayDetail.detail, workdayDetail.applyUrl);
        return;
      }
    }
    if (isPennMedicineDetail) {
      const reader = await fetchPennMedicineReaderDetail(job, source, fetcher);
      if (reader) enriched[index] = mergeProgramJobDetail(job, reader);
      return;
    }
    const supportsStandardCharteredDetail = (() => {
      try {
        return new URL(job.officialUrl).hostname.toLocaleLowerCase() === "jobs.standardchartered.com";
      } catch {
        return false;
      }
    })();
    if (!supportsJsonLdDetailEnrichment(job.officialUrl) && !supportsStandardCharteredDetail) return;
    try {
      const response = await fetchWithTimeout(fetcher, job.officialUrl, undefined, true, { attempts: 1, timeoutMs: 4_000 });
      if (response.ok) {
        const html = await response.text();
        if (supportsStandardCharteredDetail) {
          const detail = standardCharteredDetail(html, source, job, response.url || job.officialUrl);
          if (detail) {
            enriched[index] = mergeProgramJobDetail(job, detail.detail, detail.applyUrl);
            return;
          }
        }
        const detail = matchingJsonLdDetail(html, source, job);
        if (detail) {
          const merged = mergeProgramJobDetail(job, detail, officialApplyUrl(html, response.url || job.officialUrl));
          enriched[index] = merged;
          // Barclays can serve a reduced JSON-LD variant to Worker egress:
          // description/location/date are present, while the JR requisition
          // and Workday apply anchor are omitted. Keep the useful direct-page
          // fields, but continue to the identity-checked reader so a partial
          // detail response cannot silently suppress the application URL.
          if (!isBarclaysDetail || (merged.requisitionId && merged.applyUrl)) return;
        }
      }
    } catch {
      // A detail page is optional and must never make its verified listing fail.
    }
    // Barclays serves the listing to Worker egress consistently, but its
    // individual TalentBrew detail page can omit structured data or reject the
    // same request. The text reader is used only as an identity-checked detail
    // fallback; the canonical and apply links remain first-party Barclays URLs.
    if (isBarclaysDetail) {
      const current = enriched[index];
      const reader = await fetchBarclaysReaderDetail(current, source, fetcher);
      if (reader) enriched[index] = mergeProgramJobDetail(current, reader.detail, reader.applyUrl);
    }
  };
  await Promise.all(selectedTargets.map(enrichOne));
  return { ...result, jobs: enriched };
};

const applyLargeCatalogRegionScope = (result: SourceCrawlResult, source: CrawlSource): SourceCrawlResult => {
  if (result.status !== "succeeded" || !US_SCOPED_LARGE_CATALOGS.has(source.id)) return result;
  const jobs = result.jobs.filter((job) => classifyJobRegion({
    location: job.location,
    locationCity: job.locationCity,
    locationState: job.locationState,
    locationCountry: job.locationCountry,
    secondaryLocations: job.secondaryLocations,
    sourceCompany: source.company,
    sourcePostingUrl: result.resolvedListingUrl ?? source.postingUrl,
  }) !== "non_us");
  // Native facet counts describe the unscoped global catalog. Dropping them
  // lets complete crawls derive accurate US-scoped facets, while incomplete
  // checkpoint segments leave the last authoritative facet snapshot intact.
  return { ...result, jobs, facets: undefined };
};

const withLargeCatalogRequestScope = (source: CrawlSource): CrawlSource => (
  US_SCOPED_LARGE_CATALOGS.has(source.id)
    ? { ...source, regionScope: "us" }
    : source
);

export async function crawlSource(source: CrawlSource, fetcher: typeof fetch, now: Date): Promise<SourceCrawlResult> {
  const budgetedFetcher = crawlBudgetedFetcher(fetcher);
  const requestScopedSource = withLargeCatalogRequestScope(source);
  const scoped = applyLargeCatalogRegionScope(await crawlSourceBase(requestScopedSource, budgetedFetcher, now), source);
  const enriched = await enrichProgramJobDetails(scoped, source, budgetedFetcher, now);
  return applyLargeCatalogRegionScope(enriched, source);
}
